def diameterOfBinaryTree(root):
    max_diameter = [0]
    def height(node):
        if not node:
            return 0
        left_h = height(node.left)
        right_h = height(node.right)
        max_diameter[0] = max(max_diameter[0], left_h + right_h)
        return 1 + max(left_h, right_h)
    height(root)
    return max_diameter[0]

def isBalanced(root):
    def check(node):
        if not node:
            return 0
        left = check(node.left)
        if left == -1:
            return -1
        right = check(node.right)
        if right == -1:
            return -1
        if abs(left - right) > 1:
            return -1
        return 1 + max(left, right)
    return check(root) != -1

def countNodes(root):
    if not root:
        return 0
    left_h = right_h = 0
    left = right = root
    while left:
        left_h += 1
        left = left.left
    while right:
        right_h += 1
        right = right.right
    if left_h == right_h:
        return 2**left_h - 1  # perfect binary tree
    return 1 + countNodes(root.left) + countNodes(root.right)

