from collections import deque

def distanceK(root, target_val, k):
    # Build parent map
    parent = {}
    def dfs_parents(node, par):
        if not node: return
        parent[node.val] = par
        dfs_parents(node.left, node)
        dfs_parents(node.right, node)
    dfs_parents(root, None)

    # Find target node
    def find_target(node, val):
        if not node: return None
        if node.val == val: return node
        return find_target(node.left, val) or find_target(node.right, val)
    target = find_target(root, target_val)

    # BFS from target
    visited = set()
    queue = deque([(target, 0)])
    result = []
    while queue:
        node, dist = queue.popleft()
        if node.val in visited: continue
        visited.add(node.val)
        if dist == k:
            result.append(node.val)
        elif dist < k:
            for neighbor in [node.left, node.right, parent[node.val]]:
                if neighbor and neighbor.val not in visited:
                    queue.append((neighbor, dist + 1))
    return result

