def generateTrees(n):
    def generate(start, end):
        if start > end:
            return [None]
        trees = []
        for root_val in range(start, end + 1):
            lefts = generate(start, root_val - 1)
            rights = generate(root_val + 1, end)
            for left in lefts:
                for right in rights:
                    root = TreeNode(root_val)
                    root.left = left
                    root.right = right
                    trees.append(root)
        return trees
    return generate(1, n)

