def maxPathSum(root):
    max_sum = [float('-inf')]

    def gain(node):
        if not node:
            return 0
        left_gain = max(0, gain(node.left))
        right_gain = max(0, gain(node.right))
        # Path through this node
        max_sum[0] = max(max_sum[0], node.val + left_gain + right_gain)
        # Return the best single-direction path
        return node.val + max(left_gain, right_gain)

    gain(root)
    return max_sum[0]

class Codec:
    def serialize(self, root):
        result = []
        def preorder(node):
            if not node:
                result.append("#")
                return
            result.append(str(node.val))
            preorder(node.left)
            preorder(node.right)
        preorder(root)
        return ",".join(result)

    def deserialize(self, data):
        tokens = iter(data.split(","))
        def build():
            token = next(tokens)
            if token == "#":
                return None
            node = TreeNode(int(token))
            node.left = build()
            node.right = build()
            return node
        return build()

