def recoverTreeMorris(root):
    first = second = prev = None
    curr = root

    while curr:
        if not curr.left:
            # Process curr
            if prev and prev.val > curr.val:
                if not first: first = prev
                second = curr
            prev = curr
            curr = curr.right
        else:
            # Find inorder predecessor
            predecessor = curr.left
            while predecessor.right and predecessor.right is not curr:
                predecessor = predecessor.right
            if not predecessor.right:
                predecessor.right = curr  # thread it
                curr = curr.left
            else:
                predecessor.right = None  # unthread
                if prev and prev.val > curr.val:
                    if not first: first = prev
                    second = curr
                prev = curr
                curr = curr.right

    if first and second:
        first.val, second.val = second.val, first.val

