def constructFromPrePost(preorder, postorder):
    post_index = {val: i for i, val in enumerate(postorder)}

    def build(pre_start, pre_end, post_start, post_end):
        if pre_start > pre_end:
            return None
        root = TreeNode(preorder[pre_start])
        if pre_start == pre_end:
            return root
        # Left child root is preorder[pre_start + 1]
        left_root_val = preorder[pre_start + 1]
        left_size = post_index[left_root_val] - post_start + 1
        root.left = build(pre_start + 1, pre_start + left_size, post_start, post_start + left_size - 1)
        root.right = build(pre_start + left_size + 1, pre_end, post_start + left_size, post_end - 1)
        return root

    n = len(preorder)
    return build(0, n - 1, 0, n - 1)

