def pathSum(root, targetSum):

    prefix = defaultdict(int)

    prefix[0] = 1

    def dfs(node, curr_sum):

        if not node:

            return 0

        curr_sum += node.val

        count = prefix[curr_sum - targetSum]

        prefix[curr_sum] += 1

        count += dfs(node.left, curr_sum) + dfs(node.right, curr_sum)

        prefix[curr_sum] -= 1

        return count

    return dfs(root, 0)



