def isValidBSTIterative(root):

    stack, prev = [], float('-inf')

    curr = root

    while curr or stack:

        while curr:

            stack.append(curr)

            curr = curr.left

        curr = stack.pop()

        if curr.val <= prev:

            return False

        prev = curr.val

        curr = curr.right

