from collections import defaultdict



def countHighestScoreNodes(parents):

    n = len(parents)

    children = defaultdict(list)

    for child, parent in enumerate(parents):

        if parent != -1:

            children[parent].append(child)

    subtree_size = [1] * n

    # Postorder to compute sizes

    def dfs(node):

        for child in children[node]:

            dfs(child)

            subtree_size[node] += subtree_size[child]

    dfs(0)

    max_score, count = 0, 0

    for i in range(n):

        score = 1

        remaining = n - subtree_size[i]

        for child in children[i]:

            score *= subtree_size[child]

        if remaining > 0:

            score *= remaining

        if score > max_score:

            max_score, count = score, 1

        elif score == max_score:

            count += 1

    return count

