        if k == 1: return [TreeNode(0)]

        if k % 2 == 0: return []

        result = []

        for left_count in range(1, k - 1, 2):

            right_count = k - 1 - left_count

            for l in dp(left_count):

                for r in dp(right_count):

                    root = TreeNode(0)

                    root.left, root.right = l, r

                    result.append(root)

        return result

    return dp(n)



