def countNodesLogSquared(root):

    def left_height(node):

        h = 0

        while node: h += 1; node = node.left

        return h

    def right_height(node):

        h = 0

        while node: h += 1; node = node.right

        return h

    def count(node):

        if not node: return 0

        lh = left_height(node)

        rh = right_height(node)

        if lh == rh:

            return (1 << lh) - 1  # perfect binary tree: 2^h - 1

        return 1 + count(node.left) + count(node.right)

    return count(root)



